css:
[data-bz-section="athlete-directory"] [data-bz-node="ad-title"] h1 { font-weight: 700; font-size: clamp(44px, 7vw, 96px); line-height: .92; margin: 0; color: #f4fbff; }
[data-bz-node="ad-head"] { margin-bottom: 36px; }
[data-bz-node="ad-grid"] { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 36px 28px; }
[data-bz-node="ad-grid"] > .bz-col { grid-column: auto; display: flex; flex-direction: column; gap: 14px; transition: transform .3s ease; }
[data-bz-node="ad-grid"] > .bz-col:hover { transform: translateY(-6px); }
[data-bz-node="ad-grid"] > .bz-col[hidden] { display: none; }
[data-bz-node="ad-grid"] > .bz-col > .bz-block { margin: 0; }
[data-bz-node^="ad-photo"] img { width: 100%; aspect-ratio: 4 / 5; object-fit: cover; object-position: center 35%; border-radius: 14px; background: #0a2c46; }
[data-bz-node^="ad-name"] p { margin: 0; font-family: var(--font-heading); font-weight: 700; font-size: 26px; line-height: 1; text-transform: uppercase; }
[data-bz-node^="ad-name"] a { color: #f4fbff; text-decoration: none; }
[data-bz-node^="ad-meta"] { display: flex; align-items: center; gap: 10px; }
[data-bz-node^="ad-meta"] > .bz-col { width: auto; flex: none; }
[data-bz-node^="ad-flag-img"] img { width: 21px; height: 14px; object-fit: cover; border-radius: 2px; }
[data-bz-node^="ad-country-text"] p { margin: 0; font-size: 12px; letter-spacing: .2em; text-transform: uppercase; color: #00cdfd; }

