// Search, country filter, count, empty state and "Load more" for the directory.
// Without this script every card is visible, which is also what the editing canvas shows.
(function () {
  var root = document.querySelector('[data-bz-section="athlete-directory"]');
  if (!root) return;
  var cards = Array.prototype.slice.call(root.querySelectorAll('[data-bz-node="ad-grid"] > .bz-col'));
  var tools = root.querySelector('[data-athlete-filters]');
  var more = root.querySelector('[data-athlete-more]');
  if (!cards.length || !tools) return;
  var search = tools.querySelector('[data-af-search]');
  var select = tools.querySelector('[data-af-country]');
  var count = tools.querySelector('[data-af-count]');
  var empty = tools.querySelector('[data-af-empty]');
  var clear = tools.querySelector('[data-af-clear]');
  var pageSize = more ? parseInt(more.getAttribute('data-page-size'), 10) || 4 : cards.length;
  var limit = pageSize;
  var norm = function (s) { return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); };
  var info = cards.map(function (card) {
    var name = (card.querySelector('[data-bz-node^="ad-name"]') || {}).textContent || '';
    var country = (card.querySelector('[data-bz-node^="ad-country-text"]') || {}).textContent || '';
    return { card: card, country: country.trim(), hay: norm(name + ' ' + country) };
  });
  var countries = Array.from(new Set(info.map(function (i) { return i.country; }))).sort();
  countries.forEach(function (c) { var o = document.createElement('option'); o.value = c; o.textContent = c; select.appendChild(o); });
  function apply() {
    var q = norm(search.value.trim());
    var c = select.value;
    var matched = info.filter(function (i) { return (!c || i.country === c) && (!q || i.hay.indexOf(q) > -1); });
    info.forEach(function (i) { i.card.hidden = true; });
    matched.slice(0, limit).forEach(function (i) { i.card.hidden = false; });
    var n = matched.length;
    count.textContent = n === info.length ? n + ' athletes' : n + ' of ' + info.length + ' athletes';
    empty.hidden = n > 0;
    if (more) more.hidden = n <= limit;
  }
  search.addEventListener('input', function () { limit = pageSize; apply(); });
  select.addEventListener('change', function () { limit = pageSize; apply(); });
  clear.addEventListener('click', function () { search.value = ''; select.value = ''; limit = pageSize; apply(); });
  if (more) more.querySelector('button').addEventListener('click', function () { limit += pageSize; apply(); });
  apply();
})();
